lines=txt.split('\n')
leaf=0; ll={}
for i,l in enumerate(lines,1):
    ll[i]=leaf; leaf+=l.count('\f')
for n in (5056,5158,9173,9545,19819):
    print(n,'leaf',ll[n],'printed',ll[n]-20)
EOF

